-- The Campfire schema, applied to a database that has no tables yet. There
-- are no migrations: a change to this file before v1 is made to a live
-- database by hand.
--
-- Conventions (SPEC.md §13.2):
--   * Every table is STRICT: the engine rejects wrongly typed values (rule 8).
--   * Timestamps are epoch microseconds, generated by the application (rule 3).
--     No column has a DEFAULT of now() and none is filled by the database.
--   * Anything matched case-insensitively carries an explicit `*_folded`
--     column, folded at write time, with the unique index on that column;
--     the database never folds case (rule 4).
--   * Relations stay relational: join tables, never array columns (rule 7).
--
-- Two team columns appear on `items` and mean different things (SPEC.md §6.3):
--   origin_team_id  the team whose counter minted `number`. Immutable. With
--                   `number` it forms the identifier, e.g. SOL-42.
--   team_id         the owning team. Every query about ownership reads this.
--                   Reassignable for buckets only, by an instance administrator.

CREATE TABLE users (
    id             INTEGER PRIMARY KEY,
    username       TEXT    NOT NULL,
    username_folded TEXT   NOT NULL,
    password_hash  TEXT    NOT NULL,
    email          TEXT,
    email_folded   TEXT,
    totp_secret    TEXT,
    avatar         TEXT,
    -- Prose about themselves, for their profile page. Nothing reads it.
    bio            TEXT,
    is_admin       INTEGER NOT NULL DEFAULT 0,
    created_at     INTEGER NOT NULL
) STRICT;

CREATE UNIQUE INDEX users_username_folded ON users (username_folded);
CREATE UNIQUE INDEX users_email_folded ON users (email_folded) WHERE email_folded IS NOT NULL;

-- Sessions live in the database, never in process memory, so that a restart
-- is invisible rather than a mass logout (rule 5).
CREATE TABLE sessions (
    id           INTEGER PRIMARY KEY,
    token_hash   TEXT    NOT NULL,
    user_id      INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   INTEGER NOT NULL,
    last_used_at INTEGER NOT NULL,
    expires_at   INTEGER NOT NULL
) STRICT;

CREATE UNIQUE INDEX sessions_token_hash ON sessions (token_hash);
CREATE INDEX sessions_user ON sessions (user_id);

-- An agent token is a credential, not an entity (SPEC.md §14.2). It names a
-- user and carries no permissions of its own.
CREATE TABLE agent_tokens (
    id           INTEGER PRIMARY KEY,
    token_hash   TEXT    NOT NULL,
    user_id      INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name         TEXT    NOT NULL,
    created_at   INTEGER NOT NULL,
    last_used_at INTEGER,
    revoked_at   INTEGER
) STRICT;

CREATE UNIQUE INDEX agent_tokens_token_hash ON agent_tokens (token_hash);
CREATE INDEX agent_tokens_user ON agent_tokens (user_id);

-- One-time links: invitations and administrator-issued password resets. No
-- flow depends on email delivery (SPEC.md §5.1), so both are links an
-- administrator hands over out of band.
CREATE TABLE one_time_links (
    id         INTEGER PRIMARY KEY,
    token_hash TEXT    NOT NULL,
    kind       TEXT    NOT NULL CHECK (kind IN ('invite', 'reset')),
    user_id    INTEGER REFERENCES users (id) ON DELETE CASCADE,
    created_by INTEGER NOT NULL REFERENCES users (id),
    created_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL,
    used_at    INTEGER
) STRICT;

CREATE UNIQUE INDEX one_time_links_token_hash ON one_time_links (token_hash);

-- Rate-limit counters are rows, not in-process state (rule 5).
CREATE TABLE rate_limits (
    bucket       TEXT    NOT NULL PRIMARY KEY,
    window_start INTEGER NOT NULL,
    count        INTEGER NOT NULL
) STRICT;

CREATE TABLE teams (
    id               INTEGER PRIMARY KEY,
    name             TEXT    NOT NULL,
    name_folded      TEXT    NOT NULL,
    short_code       TEXT    NOT NULL,
    short_code_folded TEXT   NOT NULL,
    -- Which rendering of the fixed bucket icon set this team's surfaces use
    -- (SPEC.md §6.2). Presentation only; it never changes which icon a bucket
    -- carries.
    icon_rendering   TEXT    NOT NULL DEFAULT 'mono'
                     CHECK (icon_rendering IN ('mono', 'colour')),
    -- One counter per team, shared by tickets and buckets (SPEC.md §6.3).
    next_number      INTEGER NOT NULL DEFAULT 1,
    -- A picture and a paragraph for the team's profile page. Nothing reads them.
    avatar           TEXT,
    description      TEXT,
    archived_at      INTEGER,
    created_at       INTEGER NOT NULL
) STRICT;

-- A short code is never reused, including after archival: the row survives
-- archival, so the unique index is the whole enforcement.
CREATE UNIQUE INDEX teams_short_code_folded ON teams (short_code_folded);
CREATE UNIQUE INDEX teams_name_folded ON teams (name_folded);

CREATE TABLE team_members (
    team_id INTEGER NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role    TEXT    NOT NULL CHECK (role IN ('admin', 'member')),
    added_at INTEGER NOT NULL,
    PRIMARY KEY (team_id, user_id)
) STRICT;

CREATE INDEX team_members_user ON team_members (user_id);

-- A board column. Exactly one state per team holds each of the four roles;
-- an intermediate state has role NULL (SPEC.md §7.1).
CREATE TABLE work_states (
    id          INTEGER PRIMARY KEY,
    team_id     INTEGER NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
    name        TEXT    NOT NULL,
    name_folded TEXT    NOT NULL,
    role        TEXT    CHECK (role IN ('default', 'accepted', 'rejected', 'final')),
    position    INTEGER NOT NULL,
    created_at  INTEGER NOT NULL
) STRICT;

CREATE UNIQUE INDEX work_states_team_role ON work_states (team_id, role) WHERE role IS NOT NULL;
CREATE UNIQUE INDEX work_states_team_name ON work_states (team_id, name_folded);
CREATE INDEX work_states_team_position ON work_states (team_id, position);

-- Tickets and buckets share one table, discriminated by `kind` (SPEC.md §4).
CREATE TABLE items (
    id             INTEGER PRIMARY KEY,
    kind           TEXT    NOT NULL CHECK (kind IN ('ticket', 'bucket')),
    origin_team_id INTEGER NOT NULL REFERENCES teams (id),
    number         INTEGER NOT NULL,
    team_id        INTEGER NOT NULL REFERENCES teams (id),
    title          TEXT    NOT NULL,
    description    TEXT    NOT NULL DEFAULT '',
    reporter_id    INTEGER NOT NULL REFERENCES users (id),
    assignee_id    INTEGER REFERENCES users (id),
    priority       INTEGER NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 4),
    -- Buckets only, one of the fixed set (DESIGN.md §4). A ticket has none.
    icon           TEXT,
    -- Buckets only, one of the fixed set, optional: a bucket's tickets are
    -- recognisable on a board at a glance.
    color          TEXT,
    -- Tickets only. A bucket never belongs to another bucket (SPEC.md §6.2).
    bucket_id      INTEGER REFERENCES items (id),
    state_id       INTEGER NOT NULL REFERENCES work_states (id),
    planned_end    TEXT,
    actual_start   INTEGER,
    actual_end     INTEGER,
    reject_reason  TEXT CHECK (reject_reason IN ('cancelled', 'duplicate')),
    reject_note    TEXT,
    -- Lexical rank within the item's state, alphabet 0-9A-Za-z (SPEC.md §9.3).
    -- TEXT compares byte-wise in SQLite, which is the binary collation the
    -- rule asks for; stated here so nobody adds NOCASE later.
    rank           TEXT    NOT NULL COLLATE BINARY,
    -- Optimistic concurrency (rule 1): compare-and-swap, never read-then-write.
    version        INTEGER NOT NULL DEFAULT 1,
    created_at     INTEGER NOT NULL,
    updated_at     INTEGER NOT NULL,
    CHECK (kind = 'bucket' OR icon IS NULL),
    CHECK (kind = 'ticket' OR bucket_id IS NULL)
) STRICT;

-- The backstop for atomic identifier allocation (rule 2).
CREATE UNIQUE INDEX items_identifier ON items (origin_team_id, number);
-- Two clients can compute the same midpoint from the same read; this makes
-- the loser retry instead of silently colliding (SPEC.md §9.3).
CREATE UNIQUE INDEX items_state_rank ON items (state_id, rank);
CREATE INDEX items_team_state ON items (team_id, state_id);
CREATE INDEX items_bucket ON items (bucket_id) WHERE bucket_id IS NOT NULL;
CREATE INDEX items_assignee ON items (assignee_id) WHERE assignee_id IS NOT NULL;
CREATE INDEX items_reporter ON items (reporter_id);
CREATE INDEX items_kind ON items (kind);
-- The date fields a query filters on.
CREATE INDEX items_created ON items (created_at);
CREATE INDEX items_started ON items (actual_start) WHERE actual_start IS NOT NULL;
CREATE INDEX items_completed ON items (actual_end) WHERE actual_end IS NOT NULL;
CREATE INDEX items_due ON items (planned_end) WHERE planned_end IS NOT NULL;

-- Labels are free text, instance-wide, created by typing them (SPEC.md §8.1).
CREATE TABLE labels (
    id          INTEGER PRIMARY KEY,
    name        TEXT    NOT NULL,
    name_folded TEXT    NOT NULL,
    created_at  INTEGER NOT NULL
) STRICT;

CREATE UNIQUE INDEX labels_name_folded ON labels (name_folded);

CREATE TABLE item_labels (
    item_id  INTEGER NOT NULL REFERENCES items (id) ON DELETE CASCADE,
    label_id INTEGER NOT NULL REFERENCES labels (id) ON DELETE CASCADE,
    PRIMARY KEY (item_id, label_id)
) STRICT;

CREATE INDEX item_labels_label ON item_labels (label_id);

-- One directed edge, stored once, displayed from both ends (SPEC.md §8.2).
CREATE TABLE relations (
    id           INTEGER PRIMARY KEY,
    from_item_id INTEGER NOT NULL REFERENCES items (id) ON DELETE CASCADE,
    to_item_id   INTEGER NOT NULL REFERENCES items (id) ON DELETE CASCADE,
    kind         TEXT    NOT NULL
                 CHECK (kind IN ('blocks', 'follows_up', 'duplicates', 'relates_to')),
    created_by   INTEGER NOT NULL REFERENCES users (id),
    created_at   INTEGER NOT NULL,
    CHECK (from_item_id <> to_item_id)
) STRICT;

CREATE UNIQUE INDEX relations_edge ON relations (from_item_id, to_item_id, kind);
CREATE INDEX relations_to ON relations (to_item_id);

CREATE TABLE comments (
    id         INTEGER PRIMARY KEY,
    item_id    INTEGER NOT NULL REFERENCES items (id) ON DELETE CASCADE,
    author_id  INTEGER NOT NULL REFERENCES users (id),
    body       TEXT    NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
) STRICT;

CREATE INDEX comments_item ON comments (item_id, id);

-- A named CSQL query, owned by one team (SPEC.md §9.4). The query is stored in
-- its canonical form, naming what it references by #id, so a rename changes
-- nothing and a deleted referent matches nothing.
CREATE TABLE saved_views (
    id          INTEGER PRIMARY KEY,
    team_id     INTEGER NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
    name        TEXT    NOT NULL,
    name_folded TEXT    NOT NULL,
    query       TEXT    NOT NULL DEFAULT '',
    pin_board   INTEGER NOT NULL DEFAULT 0,
    pin_backlog INTEGER NOT NULL DEFAULT 0,
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL
) STRICT;

CREATE UNIQUE INDEX saved_views_team_name ON saved_views (team_id, name_folded);

-- What each view's query names by id, kept beside the text: a label a view
-- names MUST NOT be reaped, and a deleted referent is named wherever the view
-- is offered.
--
-- `ref_id` deliberately carries no foreign key. A row MUST NOT be removed by
-- cascade when its referent is deleted: the condition is kept, matches
-- nothing, and names the missing reference.
CREATE TABLE saved_view_refs (
    id         INTEGER PRIMARY KEY,
    view_id    INTEGER NOT NULL REFERENCES saved_views (id) ON DELETE CASCADE,
    dimension  TEXT    NOT NULL
               CHECK (dimension IN ('state', 'label', 'assignee', 'reporter', 'bucket', 'team')),
    ref_id     INTEGER
) STRICT;

CREATE INDEX saved_view_refs_view ON saved_view_refs (view_id);
CREATE INDEX saved_view_refs_ref ON saved_view_refs (dimension, ref_id);

-- One append-only table serves every history surface (SPEC.md §10). Rows are
-- never edited or deleted. `seq` is monotonic and is also the resume cursor
-- for live updates (§12.2); AUTOINCREMENT guarantees it is never reused.
--
-- Anything filterable is a real column. There is no opaque payload.
CREATE TABLE events (
    seq            INTEGER PRIMARY KEY AUTOINCREMENT,
    at             INTEGER NOT NULL,
    actor_id       INTEGER REFERENCES users (id),
    -- The agent token the call arrived on, null for anything done in the
    -- client (SPEC.md §14.4). A real column because "what did agents do here"
    -- is a question an administrator asks.
    agent_token_id INTEGER REFERENCES agent_tokens (id),
    kind           TEXT    NOT NULL,
    entity         TEXT    NOT NULL
                   CHECK (entity IN ('item', 'comment', 'team', 'user',
                                     'saved_view', 'work_state', 'instance')),
    entity_id      INTEGER,
    -- Denormalised so that item history and the SSE fan-out are one indexed
    -- read; both are null for instance-level events.
    item_id        INTEGER,
    team_id        INTEGER,
    field          TEXT,
    old_value      TEXT,
    new_value      TEXT
) STRICT;

CREATE INDEX events_item ON events (item_id, seq) WHERE item_id IS NOT NULL;
CREATE INDEX events_team ON events (team_id, seq) WHERE team_id IS NOT NULL;
CREATE INDEX events_actor ON events (actor_id, seq);
CREATE INDEX events_agent ON events (agent_token_id, seq) WHERE agent_token_id IS NOT NULL;
